                else:
                    raise ValueError(f"Invalid action space {self.action_space=} for {self.args.user_prompt_prefix=}")
            elif self.args.user_prompt_prefix == "explorative_v1":
                if self.action_space == "pyautogui":
                    _user_prompt = _user_prompt + "\n" + USR_PROMPT_EXPLORATIVE_IN_A11Y_OUT_CODE
                elif self.action_space == "computer_13":
                    raise ValueError(f"Invalid action space {self.action_space=} for {self.args.user_prompt_prefix=}")
                else:
                    raise ValueError(f"Invalid action space {self.action_space=} for {self.args.user_prompt_prefix=}")

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": _user_prompt
                    }
                ]
            })
        elif self.observation_type == "som":
            base64_image = obs_post["screenshot"]
            linearized_accessibility_tree = obs_post["accessibility_tree"]
            _user_prompt = "Given the tagged screenshot and info from accessibility tree as below:\n{}\nWhat's the next step that you will do to help with the task?".format(
                            linearized_accessibility_tree)

            if self.args.user_prompt_prefix == "reasoning_v1":
                raise ValueError(f"Invalid action space {self.action_space=} for {self.args.user_prompt_prefix=}")
            elif self.args.user_prompt_prefix == "explorative_v1":
                raise ValueError(f"Invalid action space {self.action_space=} for {self.args.user_prompt_prefix=}")

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": _user_prompt
                    },
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:image/png;base64,{base64_image}",
                            "detail": "high"
                        }
                    }
                ]
            })
        else:
            raise ValueError("Invalid observation_type type: " + self.observation_type)
        return messages

exact.agentic.retriever.FaissRetriever.source_code:
class FaissRetriever:
    def __init__(
        self,
        index_save_path: str,
        docs: list[Document],
        embeddings: OpenAIEmbeddings = None,
        **kwargs
    ):
        fs = LocalFileStore(index_save_path)

        self.docs = docs
        self.embeddings = CacheBackedEmbeddings.from_bytes_store(
            embeddings, fs, namespace="faiss"
        )
        self.retriever = self._init_retriever(**kwargs)
        return

    def _init_retriever(self, **kwargs):
        docsearch = FAISS.from_documents(
            self.docs, self.embeddings,
            distance_strategy=DistanceStrategy.COSINE
        )
        # retriever = docsearch.as_retriever(**kwargs)
        return docsearch

    @time_it
    def retrieve(self, query: str, min_score: float = 0.2, k: int = 3) -> list[Document]:
        self.retriever: FAISS
        docs_w_score = self.retriever._similarity_search_with_relevance_scores(query, k=k)
        logger.debug(f"retrieved {len(docs_w_score)} docs with scores {[score for _, score in docs_w_score]}")
        docs = []
        for doc, score in docs_w_score:
            if score >= min_score:
                docs.append(doc)
        return docs

exact.agentic.rpolicy_prompt.PolicyRefle.source_code:
class PolicyReflectionRecord:
    # important!
    instruction: str
    state_str: str
    state_img_arr: np.ndarray
    response_str: str
    next_state_str: str
    next_state_img_arr: Optional[np.ndarray]
    reflection: str
    _from_task_hash: str  # map back to the task record

    def __hash__(self):
        # !! python's built-in hash() is not deterministic
        unique_str = self.instruction + self.state_str + self.response_str + self.next_state_str + self.reflection
        hash_object = hashlib.md5(unique_str.encode())
        hash_int = int(hash_object.hexdigest(), 16)
        return hash_int

    def simplified_info(self) -> dict:
        return {
            "instruction": self.instruction,
            "reflection": self.reflection,
            "hash": hash(self),
        }

    def __eq__(self, other):
        if not isinstance(other, PolicyReflectionRecord):
            return False
        return hash(self) == hash(other)

